const raw = $input.first().json;
const body = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
const params = body.params || {};
return [{ json: {
  jobId: body.jobId || '',
  callbackUrl: body.callbackUrl || '',
  callbackSecret: body.callbackSecret || '',
  skillBaseUrl: body.skillBaseUrl || '',
  texto_ocr: String(body.textoOcr || ''),
  total_paginas: body.totalPaginas ?? null,
  incluir_memorial: String(params.incluirMemorial ?? 'true').toLowerCase() === 'true',
  incluir_croqui: String(params.incluirCroqui ?? 'false').toLowerCase() === 'true',
  geocodificar: String(params.geocodificar ?? 'true').toLowerCase() === 'true',
} }];

